import { path } from '@servicenow/sdk-build-core'
import { createTestContext, loadTestFile, unzipInputArray } from '../test-utils'
import { XMLParser } from 'fast-xml-parser'

/**
 * Round-Trip Test: assign-subflow-primitive-arrays
 *
 * XML Source: sys_hub_flow_f5a4bc6563fc499a8fdce89d58d2638f.xml
 * Fluent Source: assign-subflow-primitive-arrays.now.ts
 *
 * Subflow Name: Test Subflow - Primitive Arrays
 * Description: Subflow with primitive type FlowArray outputs
 *
 * Features Tested:
 * - Subflow definition with inputs (string, integer, boolean, datetime)
 * - FlowArray outputs (string, integer, boolean, datetime)
 * - assignSubflowOutputs logic with 11 TEST cases
 * - Data value validations (literals, datapills, empty arrays)
 * - XML → Fluent → XML round-trip transformation
 */

/**
 * Helper function to validate imports in generated Fluent code
 * @param content - The Fluent code content to validate
 * @param expectedImports - Array of expected import strings
 */
function validateImports(content: string, expectedImports: string[]) {
    expect(content).toContain('import {')
    expectedImports.forEach((importName) => {
        expect(content).toContain(importName)
    })
}

describe('assign-subflow-primitive-arrays: Round-Trip Test', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    /**
     * Test: assign-subflow-primitive-arrays
     * XML: sys_hub_flow_f5a4bc6563fc499a8fdce89d58d2638f.xml
     * Type: Subflow
     * Features: FlowArray outputs (string, number, boolean, date), assignSubflowOutputs logic
     */
    test('assign-subflow-primitive-arrays: Round-trip transformation', async () => {
        const xmlFileName = 'sys_hub_flow_f5a4bc6563fc499a8fdce89d58d2638f.xml'
        const project = ctx.createProject()

        // ============================================================================
        // Step 1: XML → Fluent Transformation
        // ============================================================================
        const xmlContent = loadTestFile(xmlFileName, 'example-unit-tests/xml')
        const { changedFiles } = await project.transform({
            path: xmlFileName,
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        const fluentContent = changedFiles[0].getContent()
        const fluentFileName = changedFiles[0].getName()

        // Verify imports
        validateImports(fluentContent, [
            'Subflow',
            'FlowArray',
            'StringColumn',
            'IntegerColumn',
            'BooleanColumn',
            'DateTimeColumn',
        ])

        // Verify subflow definition
        expect(fluentContent).toContain('Subflow(')
        expect(fluentContent).toContain("name: 'Test Subflow - Primitive Arrays'")
        expect(fluentContent).toContain("description: 'Subflow with primitive type FlowArray outputs'")

        // Verify inputs
        expect(fluentContent).toContain('inputs: {')
        expect(fluentContent).toContain('inputString: StringColumn(')
        expect(fluentContent).toContain('inputNumber: IntegerColumn(')
        expect(fluentContent).toContain('inputBoolean: BooleanColumn(')
        expect(fluentContent).toContain('inputDate: DateTimeColumn(')

        // Verify FlowArray outputs with elementType
        expect(fluentContent).toContain('outputs: {')
        expect(fluentContent).toContain('stringList: FlowArray(')
        expect(fluentContent).toContain('numberList: FlowArray(')
        expect(fluentContent).toContain('booleanList: FlowArray(')
        expect(fluentContent).toContain('dateList: FlowArray(')
        expect(fluentContent).toContain('elementType: StringColumn(')
        expect(fluentContent).toContain('elementType: IntegerColumn(')
        expect(fluentContent).toContain('elementType: BooleanColumn(')

        // Verify childName attributes
        expect(fluentContent).toContain("childName: 'stringItem'")
        expect(fluentContent).toContain("childName: 'numberItem'")

        // Verify assignSubflowOutputs calls
        expect(fluentContent).toContain('wfa.flowLogic.assignSubflowOutputs(')
        expect(fluentContent).toContain('_params.outputs')

        // Verify TEST 1 data values (string array with values)
        expect(fluentContent).toContain("stringList: ['apple', 'banana', 'cherry']")

        // Verify TEST 2 data values (integer array with values)
        expect(fluentContent).toContain('numberList: [10, 20, 30, 40]')

        // Verify TEST 3 data values (boolean array with values)
        expect(fluentContent).toContain('booleanList: [true, false, true]')

        // Verify TEST 4 data values (datetime array with values)
        expect(fluentContent).toContain("dateList: ['2024-01-01 10:00:00', '2024-02-15 14:30:00']")

        // Verify TEST 5-7 data values (empty arrays)
        expect(fluentContent).toContain('stringList: []')
        expect(fluentContent).toContain('numberList: []')
        expect(fluentContent).toContain('booleanList: []')

        // Verify TEST 8 data values (string array with datapills)
        expect(fluentContent).toContain("'Static value'")
        expect(fluentContent).toMatch(/wfa\.dataPill\(.*_params\.inputs\.inputString/)
        expect(fluentContent).toMatch(/Computed:.*wfa\.dataPill/)

        // Verify TEST 9 data values (integer array with datapills)
        expect(fluentContent).toContain('numberList: [100,')
        expect(fluentContent).toMatch(/wfa\.dataPill\(.*_params\.inputs\.inputNumber/)
        expect(fluentContent).toContain(', 200]')

        // Verify TEST 10 data values (boolean array with datapills)
        expect(fluentContent).toContain('booleanList: [true,')
        expect(fluentContent).toMatch(/wfa\.dataPill\(.*_params\.inputs\.inputBoolean/)
        expect(fluentContent).toContain(', false]')

        // Verify TEST 11 data values (datetime array with datapills)
        expect(fluentContent).toContain("dateList: [\n                    '2024-01-01 10:00:00',")
        expect(fluentContent).toMatch(/wfa\.dataPill\(.*_params\.inputs\.inputDate/)
        expect(fluentContent).toContain("'2024-12-31 23:59:59'")

        // Verify final log action
        expect(fluentContent).toContain("log_message: 'All primitive array tests completed'")

        // Verify annotations are present
        expect(fluentContent).toContain('annotation:')

        // ============================================================================
        // Step 2: Fluent → XML Transformation
        // ============================================================================
        const tempProject = ctx.createProject()
        tempProject.addFile({ path: fluentFileName, content: fluentContent })

        const output = await tempProject.getFile(fluentFileName)!.getOutput()
        expect(output.length).toBeGreaterThan(0)

        // ============================================================================
        // Step 3: Parse and Validate Regenerated XML
        // ============================================================================
        const parser = new XMLParser({ ignoreAttributes: false })
        const mergedRecords: Record<string, any[]> = {}

        for (const file of output) {
            const parsed = parser.parse(file.content)['record_update']
            Object.entries(parsed).forEach(([table, value]) => {
                if (!mergedRecords[table]) {
                    mergedRecords[table] = []
                }
                if (Array.isArray(value)) {
                    mergedRecords[table].push(...value)
                } else if (value && typeof value === 'object') {
                    mergedRecords[table].push(value)
                }
            })
        }

        // Verify expected XML tables exist
        expect(mergedRecords['sys_hub_flow']).toBeDefined()
        expect(mergedRecords['sys_hub_flow_output']).toBeDefined()
        expect(mergedRecords['sys_hub_flow_input']).toBeDefined()
        expect(mergedRecords['sys_hub_flow_logic_instance_v2']).toBeDefined()

        // ============================================================================
        // Step 4: Validate Subflow Record
        // ============================================================================
        const subflows = mergedRecords['sys_hub_flow']
        expect(subflows.length).toBeGreaterThanOrEqual(1)
        const subflow = subflows.find((s: any) => s.name === 'Test Subflow - Primitive Arrays')
        expect(subflow).toBeDefined()
        expect(subflow.description).toBe('Subflow with primitive type FlowArray outputs')
        expect(subflow.type).toBe('subflow')
        expect(subflow.generation_source).toBe('fluent')

        // ============================================================================
        // Step 5: Validate Outputs
        // ============================================================================
        const outputs = mergedRecords['sys_hub_flow_output']
        expect(outputs.length).toBeGreaterThanOrEqual(4)

        // Verify stringList output
        const stringList = outputs.find((o: any) => o.element === 'stringList')
        expect(stringList).toBeDefined()
        expect(stringList.label).toBe('String List')
        expect(stringList.mandatory).toBe(false)
        expect(stringList.active).toBe(true)

        // Verify numberList output
        const numberList = outputs.find((o: any) => o.element === 'numberList')
        expect(numberList).toBeDefined()
        expect(numberList.label).toBe('Number List')
        expect(numberList.mandatory).toBe(false)
        expect(numberList.active).toBe(true)

        // Verify booleanList output
        const booleanList = outputs.find((o: any) => o.element === 'booleanList')
        expect(booleanList).toBeDefined()
        expect(booleanList.label).toBe('Boolean List')
        expect(booleanList.mandatory).toBe(false)
        expect(booleanList.active).toBe(true)

        // Verify dateList output
        const dateList = outputs.find((o: any) => o.element === 'dateList')
        expect(dateList).toBeDefined()
        expect(dateList.label).toBe('Date List')
        expect(dateList.mandatory).toBe(false)
        expect(dateList.active).toBe(true)

        // ============================================================================
        // Step 5a: Validate Flow Logic Data Values (Decompress and Verify)
        // ============================================================================
        const flowLogics = mergedRecords['sys_hub_flow_logic_instance_v2']
        expect(flowLogics.length).toBeGreaterThanOrEqual(11) // 11 TEST cases

        // TEST 1: String array with values
        const test1 = flowLogics.find((fl: any) => fl.comment === 'TEST 1: String Array')
        expect(test1).toBeDefined()
        const test1Values = unzipInputArray(test1.values) as any
        const test1StringList = test1Values.outputsToAssign.find((v: any) => v.name === 'stringList')
        expect(test1StringList).toBeDefined()
        expect(test1StringList.value).toContain('["apple","banana","cherry"]')

        // TEST 2: Integer array with values
        const test2 = flowLogics.find((fl: any) => fl.comment === 'TEST 2: Integer Array')
        expect(test2).toBeDefined()
        const test2Values = unzipInputArray(test2.values) as any
        const test2NumberList = test2Values.outputsToAssign.find((v: any) => v.name === 'numberList')
        expect(test2NumberList).toBeDefined()
        expect(test2NumberList.value).toContain('[10,20,30,40]')

        // TEST 3: Boolean array with values
        const test3 = flowLogics.find((fl: any) => fl.comment === 'TEST 3: Boolean Array')
        expect(test3).toBeDefined()
        const test3Values = unzipInputArray(test3.values) as any
        const test3BooleanList = test3Values.outputsToAssign.find((v: any) => v.name === 'booleanList')
        expect(test3BooleanList).toBeDefined()
        expect(test3BooleanList.value).toContain('[true,false,true]')

        // TEST 4: DateTime array with values
        const test4 = flowLogics.find((fl: any) => fl.comment === 'TEST 4: DateTime Array')
        expect(test4).toBeDefined()
        const test4Values = unzipInputArray(test4.values) as any
        const test4DateList = test4Values.outputsToAssign.find((v: any) => v.name === 'dateList')
        expect(test4DateList).toBeDefined()
        expect(test4DateList.value).toContain('2024-01-01 10:00:00')
        expect(test4DateList.value).toContain('2024-02-15 14:30:00')

        // TEST 5: Empty string array
        const test5 = flowLogics.find((fl: any) => fl.comment === 'TEST 5: Empty String Array')
        expect(test5).toBeDefined()
        const test5Values = unzipInputArray(test5.values) as any
        const test5StringList = test5Values.outputsToAssign.find((v: any) => v.name === 'stringList')
        expect(test5StringList).toBeDefined()
        // Empty arrays are stored as complex objects with schema
        expect(test5StringList.value).toContain('complexObject')
        expect(test5StringList.value).toContain('$COCollectionField')

        // TEST 6: Empty integer array
        const test6 = flowLogics.find((fl: any) => fl.comment === 'TEST 6: Empty Integer Array')
        expect(test6).toBeDefined()
        const test6Values = unzipInputArray(test6.values) as any
        const test6NumberList = test6Values.outputsToAssign.find((v: any) => v.name === 'numberList')
        expect(test6NumberList).toBeDefined()
        // Empty arrays are stored as complex objects with schema
        expect(test6NumberList.value).toContain('complexObject')
        expect(test6NumberList.value).toContain('$COCollectionField')

        // TEST 7: Empty boolean array
        const test7 = flowLogics.find((fl: any) => fl.comment === 'TEST 7: Empty Boolean Array')
        expect(test7).toBeDefined()
        const test7Values = unzipInputArray(test7.values) as any
        const test7BooleanList = test7Values.outputsToAssign.find((v: any) => v.name === 'booleanList')
        expect(test7BooleanList).toBeDefined()
        // Empty arrays are stored as complex objects with schema
        expect(test7BooleanList.value).toContain('complexObject')
        expect(test7BooleanList.value).toContain('$COCollectionField')

        // TEST 8: String array with datapills (verify XML format {{...}})
        const test8 = flowLogics.find((fl: any) => fl.comment === 'TEST 8: String Array with Datapills')
        expect(test8).toBeDefined()
        const test8Values = unzipInputArray(test8.values) as any
        const test8StringList = test8Values.outputsToAssign.find((v: any) => v.name === 'stringList')
        expect(test8StringList).toBeDefined()
        expect(test8StringList.value).toContain('Static value')
        expect(test8StringList.value).toContain('{{subflow.inputString}}')
        expect(test8StringList.value).toContain('Computed:')

        // TEST 9: Integer array with datapills
        const test9 = flowLogics.find((fl: any) => fl.comment === 'TEST 9: Integer Array with Datapills')
        expect(test9).toBeDefined()
        const test9Values = unzipInputArray(test9.values) as any
        const test9NumberList = test9Values.outputsToAssign.find((v: any) => v.name === 'numberList')
        expect(test9NumberList).toBeDefined()
        expect(test9NumberList.value).toContain('100')
        expect(test9NumberList.value).toContain('{{subflow.inputNumber}}')
        expect(test9NumberList.value).toContain('200')

        // TEST 10: Boolean array with datapills
        const test10 = flowLogics.find((fl: any) => fl.comment === 'TEST 10: Boolean Array with Datapills')
        expect(test10).toBeDefined()
        const test10Values = unzipInputArray(test10.values) as any
        const test10BooleanList = test10Values.outputsToAssign.find((v: any) => v.name === 'booleanList')
        expect(test10BooleanList).toBeDefined()
        expect(test10BooleanList.value).toContain('true')
        expect(test10BooleanList.value).toContain('{{subflow.inputBoolean}}')
        expect(test10BooleanList.value).toContain('false')

        // TEST 11: DateTime array with datapills
        const test11 = flowLogics.find((fl: any) => fl.comment === 'TEST 11: DateTime Array with Datapills')
        expect(test11).toBeDefined()
        const test11Values = unzipInputArray(test11.values) as any
        const test11DateList = test11Values.outputsToAssign.find((v: any) => v.name === 'dateList')
        expect(test11DateList).toBeDefined()
        expect(test11DateList.value).toContain('2024-01-01 10:00:00')
        expect(test11DateList.value).toContain('{{subflow.inputDate}}')
        expect(test11DateList.value).toContain('2024-12-31 23:59:59')

        // ============================================================================
        // Step 6: Validate Inputs
        // ============================================================================
        const inputs = mergedRecords['sys_hub_flow_input']
        expect(inputs.length).toBe(5)

        const inputString = inputs.find((i: any) => i.element === 'inputString')
        expect(inputString).toBeDefined()
        expect(inputString.label).toBe('Input String')
        expect(inputString.internal_type).toBe('string')
        expect(inputString.mandatory).toBe(false)

        const inputNumber = inputs.find((i: any) => i.element === 'inputNumber')
        expect(inputNumber).toBeDefined()
        expect(inputNumber.label).toBe('Input Number')
        expect(inputNumber.internal_type).toBe('integer')
        expect(inputNumber.mandatory).toBe(false)

        // ============================================================================
        // Step 7: Validate Flow Logic (assignSubflowOutputs)
        // ============================================================================
        const flowLogicInstances = mergedRecords['sys_hub_flow_logic_instance_v2']
        expect(flowLogicInstances.length).toBeGreaterThanOrEqual(11)

        // Test 1: String array with values
        const xmlTest1 = flowLogicInstances.find((fl: any) => fl.comment === 'TEST 1: String Array')
        expect(xmlTest1).toBeDefined()
        expect(xmlTest1.logic_definition).toBe('df4e1945c3e232002841b63b12d3ae3e')

        const xmlTest1Values = unzipInputArray(xmlTest1.values) as any
        expect(xmlTest1Values.outputsToAssign).toBeDefined()
        expect(xmlTest1Values.outputsToAssign.length).toBeGreaterThan(0)

        const xmlTest1StringList = xmlTest1Values.outputsToAssign.find((o: { name: string }) => o.name === 'stringList')
        expect(xmlTest1StringList).toBeDefined()
        expect(xmlTest1StringList.value).toBeDefined()
        expect(xmlTest1StringList.displayValue).toBeDefined()
        expect(xmlTest1StringList.value).toContain('[')

        // Test 8: String array with datapills
        const xmlTest8 = flowLogicInstances.find((fl: any) => fl.comment === 'TEST 8: String Array with Datapills')
        expect(xmlTest8).toBeDefined()
        const xmlTest8Values = unzipInputArray(xmlTest8.values) as any
        const xmlTest8StringList = xmlTest8Values.outputsToAssign.find((o: any) => o.name === 'stringList')
        expect(xmlTest8StringList).toBeDefined()
        expect(xmlTest8StringList.value).toContain('{{')
        expect(xmlTest8StringList.value).toContain('}}')
        expect(xmlTest8StringList.value).toMatch(/\{\{[^}]+\}\}/)
    })
})
